#include<bits/stdc++.h>\nusing namespace std;\n\nbool balanceParenthesis(string input){\n    if(input.empty()) return true;\n    stack<char> st;\n    \n    for(char c : input){\n        if(c == '(' || c == '{' || c == '['){\n            st.push(c);\n            continue;\n        } else if(c == ')' || c == '}' || c == ']'){\n            if(st.empty()) return false;\n            \n            if(c == ')' && st.top() == '('){\n                st.pop();\n                continue;\n            } else if(c == '}' && st.top() == '{'){\n                st.pop();\n                continue;\n            } else if(c == ']' && st.top() == '['){\n                st.pop();\n                continue;\n            } else {\n                return false;\n            }\n        } else {\n            // For characters other than brackets, we ignore them\n            continue;\n        }\n    }\n    \n    return st.empty();\n}\n\nint main() {\n    // ✅ Valid cases\n    cout << balanceParenthesis(\"()\") << \" // Expected: 1\\n\";\n    cout << balanceParenthesis(\"()[]{}\") << \" // Expected: 1\\n\";\n    cout << balanceParenthesis(\"{[()]}\") << \" // Expected: 1\\n\";\n    cout << balanceParenthesis(\"([])\") << \" // Expected: 1\\n\";\n    cout << balanceParenthesis(\"{([])}\") << \" // Expected: 1\\n\";\n\n    // ❌ Invalid cases\n    cout << balanceParenthesis(\"(]\") << \" // Expected: 0\\n\";\n    cout << balanceParenthesis(\"([)]\") << \" // Expected: 0\\n\";\n    cout << balanceParenthesis(\"{[}\") << \" // Expected: 0\\n\";\n    cout << balanceParenthesis(\"(((()\") << \" // Expected: 0\\n\";\n    cout << balanceParenthesis(\"({)}\") << \" // Expected: 0\\n\";\n\n    // 🧵 Edge case\n    cout << balanceParenthesis(\"\") << \" // Expected: 1\\n\"; // Empty string is trivially valid\n\n    // Additional test cases with non-bracket characters\n    cout << balanceParenthesis(\"a(b)c[d]e{f}\") << \" // Expected: 1\\n\"; // Non-bracket characters\n    cout << balanceParenthesis(\"hello(world[test{code}])\") << \" // Expected: 1\\n\"; // Mixed with words\n\n    return 0;\n}